import re
def sql_arguments(value):
    if not isinstance(value,dict) or set(value)!={'query_name','purchase_order_id','limit'}:
        raise ValueError('invalid_arguments')
    name=value['query_name'];key=value['purchase_order_id'];limit=value['limit']
    if type(limit) is not int or not 1<=limit<=5:raise ValueError('invalid_arguments')
    if name=='open_purchase_orders':
        if key is not None:raise ValueError('invalid_arguments')
    elif name=='purchase_order_by_id':
        if not isinstance(key,str) or re.fullmatch(r'[A-Za-z0-9_-]{1,64}',key) is None:
            raise ValueError('invalid_arguments')
    else:raise ValueError('invalid_arguments')
    return dict(value)

