from decimal import Decimal,localcontext,ROUND_HALF_EVEN
def price_change(baseline, current, base_currency, new_currency, base_unit, new_unit):
    if Decimal(baseline)<=0 or base_currency!=new_currency or base_unit!=new_unit:
        raise ValueError('incomparable_prices')
    with localcontext() as context:
        context.prec=28
        delta=Decimal(current)-Decimal(baseline)
        percent=delta/Decimal(baseline)*100
        return tuple(str(v.quantize(Decimal('0.01'),rounding=ROUND_HALF_EVEN)) for v in (delta,percent))

