import copy
def correlated_reply(expected_call_id, reply):
    if not isinstance(reply,dict) or set(reply)!={'call_id','name','status','data','error','attempts'} or reply['call_id']!=expected_call_id:
        raise ValueError('result_invalid')
    return copy.deepcopy(reply)

def error_reply(call_id, name, code, attempts):
    allowed=('invalid_arguments','unknown_tool','forbidden','not_found','approval_required','conflict','unavailable','timeout','unknown_outcome','result_invalid','tool_failed')
    if type(attempts) is not int or not 0<=attempts<=2:raise ValueError('attempts_invalid')
    safe=code if isinstance(code,str) and code in allowed else 'tool_failed'
    if safe=='unknown_outcome' and attempts!=1:raise ValueError('attempts_invalid')
    return dict(call_id=call_id,name=name,status='unknown' if safe=='unknown_outcome' else 'error',data=None,error=safe,attempts=attempts)

def evidence_ok(references, outcomes):
    if not isinstance(references,list) or len(references)>6 or not all(isinstance(x,str) for x in references):
        return False
    if len(set(references))!=len(references):return False
    successful={r['call_id'] for r in outcomes if r['status']=='ok'}
    return set(references)<=successful

import hashlib,json
def operation_digest(tenant, principal, key, arguments):
    body={'schema':'create_review/1','tenant':tenant,'principal':principal,'operation_key':key,'arguments':arguments}
    raw=json.dumps(body,sort_keys=True,ensure_ascii=False,separators=(',',':'),allow_nan=False).encode('utf-8')
    return hashlib.sha256(raw).hexdigest()

def approval_allows(writable, expected_digest, approval, now):
    return (writable is True and approval is not None
            and approval['digest']==expected_digest and now<approval['expires'])

def intent_state(ledger, scope, digest):
    if scope not in ledger:return 'new'
    return 'replay' if ledger[scope]['digest']==digest else 'conflict'

import copy
def read_saved(lookup, authorized, approved, digest):
