import copy
def store_once(ledger, scope, digest, make):
    if scope in ledger:
        row=ledger[scope]
        if row['digest']!=digest:raise ValueError('conflict')
        return copy.deepcopy(row['result']),True
    value=make()
    ledger[scope]={'digest':digest,'result':copy.deepcopy(value)}
    return copy.deepcopy(value),False

