def retry_action(effect, code, attempt):
    if effect not in ('read','write') or type(attempt) is not int or not 1<=attempt<=2 or (effect=='write' and attempt!=1):
        raise ValueError('policy_invalid')
    if effect=='read':
        return 'retry' if code in ('unavailable','timeout') and attempt==1 else 'stop'
    return 'stop' if code in ('forbidden','not_found','approval_required','conflict','invalid_arguments') else 'unknown'

async def retry_read(send, delay):
    try:
        return await send()
    except (TimeoutError,ConnectionError):
        await delay(0.05)
    return await send()

