import copy,json
def append_message(messages, message, limit):
    candidate=[*messages,message]
    raw=json.dumps(candidate,sort_keys=True,ensure_ascii=False,separators=(',',':'),allow_nan=False)
    if len(raw.encode('utf-8'))>limit:raise ValueError('transcript_budget')
    return copy.deepcopy(candidate)
